// Keep both feeds strictly newest-first regardless of insertion order.
intel.sort((a, b) => b.date.localeCompare(a.date));
deals.sort((a, b) => b.date.localeCompare(a.date));

// ---------------------------------------------------------------------------
// Commentary — credit research & white papers
// ---------------------------------------------------------------------------
// Curated primary research on credit markets — spreads, underwriting & covenant
// quality, defaults & recovery, private credit vs BSL, CLO structure — published
// by banks, asset managers, rating agencies and industry bodies. NOT deal news
// (that lives in News/Deals/Fundraising). `url` points to each publisher's
// research hub; newest first. Maintained by the four-times-daily refresh routine.
// Retired 2026-10-13: every entry linked to a publisher HOMEPAGE (not the piece), so
// none could be verified, and the array had not been refreshed since July. House
// research lives in /research.js (the Research lane, swept from the inbox). Kept as an
// empty export so existing importers keep working; do not repopulate.
export const research = [];

// ---------------------------------------------------------------------------
// Lookup helpers
// ---------------------------------------------------------------------------
export const managerById = Object.fromEntries(managers.map((m) => [m.id, m]));
export const fundById = Object.fromEntries(funds.map((f) => [f.id, f]));
export const lpById = Object.fromEntries(lps.map((l) => [l.id, l]));

export function fundsByManager(managerId) {
  return funds.filter((f) => f.managerId === managerId);
}
export function intelForManager(managerId) {
  return intel.filter((i) => i.managerId === managerId);
}
export function intelForFund(fundId) {
  return intel.filter((i) => i.fundId === fundId);
}
// Every deal the firm is a party to: filed under it, or naming it as a lender / arranger
// (`lenders[].managerId`) or as the sponsor (`sponsorId`) — HOUSE_STYLE R39m.
export function dealsForManager(managerId) {
  return deals.filter((d) => d.managerId === managerId || d.sponsorId === managerId || (d.lenders || []).some((l) => l && l.managerId === managerId));
}
export function dealsForFund(fundId) {
  return deals.filter((d) => d.fundId === fundId);
}

